/**
 * Kbd. A molded keycap for keyboard hints — a tiny
 * HardwareButton cap that never presses. Composes var(--echo-*).
 */
.echo-kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 22px;
  padding: 0 var(--echo-space-3);
  border-radius: var(--echo-radius-sm);
  font-family: var(--echo-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-2xs);
  font-weight: var(--echo-weight-bold, 700);
  line-height: var(--echo-leading-none, 1);
  color: var(--echo-text);
  background: linear-gradient(
    180deg,
    var(--echo-cap-highlight) 0%,
    var(--echo-cap) 60%,
    var(--echo-cap-shadow) 100%
  );
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.3 * var(--echo-gloss, 1))),
    inset 0 -1px 1px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent),
    0 calc(2px - 2px * var(--press, 0)) 0 var(--echo-seam),
    0 calc(3px - 2px * var(--press, 0)) calc(4px - 2px * var(--press, 0))
      color-mix(in oklab, var(--echo-cast-ink, black) calc(0.4 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
  /* Kbd presses when its real key does; the 2px of travel is its seam. */
  will-change: transform;
}

"use client";

/**
 * Kbd — a molded keycap for keyboard hints.
 *
 * It is a hint, not a control, so it never takes a click or focus. What it
 * does is go down when the key it names goes down on the real keyboard: the
 * cap under "⌘ K" presses as you press ⌘K, so the hint and the hand agree.
 * The key is read from the cap's text ("⌘", "Esc", "K"); caps whose text
 * names no key simply stay still.
 */
import { useEffect, type HTMLAttributes } from "react";
import { useCapPhysics } from "echo-ui-core/tactile";
import "./kbd.css";

export type KbdProps = HTMLAttributes<HTMLElement>;

/** The printed legend → the `KeyboardEvent.key` it stands for. */
const LEGENDS: Record<string, string> = {
  "⌘": "Meta",
  cmd: "Meta",
  command: "Meta",
  "⌃": "Control",
  ctrl: "Control",
  control: "Control",
  "⌥": "Alt",
  alt: "Alt",
  option: "Alt",
  "⇧": "Shift",
  shift: "Shift",
  esc: "Escape",
  escape: "Escape",
  "↵": "Enter",
  "⏎": "Enter",
  enter: "Enter",
  return: "Enter",
  tab: "Tab",
  "⇥": "Tab",
  space: " ",
  "␣": " ",
  "⌫": "Backspace",
  backspace: "Backspace",
  "←": "ArrowLeft",
  "→": "ArrowRight",
  "↑": "ArrowUp",
  "↓": "ArrowDown",
};

function keyForLegend(legend: unknown): string | null {
  if (typeof legend !== "string" && typeof legend !== "number") return null;
  const text = String(legend).trim();
  if (!text) return null;
  const named = LEGENDS[text] ?? LEGENDS[text.toLowerCase()];
  if (named) return named;
  return text.length === 1 ? text.toLowerCase() : null;
}

export function Kbd({ className, children, ...rest }: KbdProps) {
  const cap = useCapPhysics<HTMLElement>({ travel: 2, tilt: 0 });
  const key = keyForLegend(children);
  const { press, release } = cap;

  useEffect(() => {
    if (!key) return;
    const matches = (e: KeyboardEvent) => e.key.toLowerCase() === key.toLowerCase();
    const down = (e: KeyboardEvent) => {
      if (!e.repeat && matches(e)) press();
    };
    const up = (e: KeyboardEvent) => {
      if (matches(e)) release();
    };
    // A key held while the window loses focus never sends its keyup.
    const lost = () => release();
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    window.addEventListener("blur", lost);
    return () => {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", up);
      window.removeEventListener("blur", lost);
    };
  }, [key, press, release]);

  return (
    <kbd ref={cap.ref} className={["echo-kbd", className].filter(Boolean).join(" ")} {...rest}>
      {children}
    </kbd>
  );
}
